-- Robotics/Embedded/IoT pathway ("Vector Division") Act 29 -- "Drones"
-- content, OPENING Arc VI ("Autonomy Leaves the Lab," bible spans Acts
-- 29-31). World row world-vec-drones already exists (created by
-- 20260813360000). 1 campaign, 2 operations, 12 missions (11 lessons +
-- boss), following the same campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern as every other
-- pathway. No new ChallengeType needed -- reuses story_dialogue,
-- multiple_choice, drag_and_drop, investigation, interactive_diagram,
-- browser_simulation and boss_encounter. Vector Division brings its
-- first aerial platform online -- a small inspection drone that loses
-- GPS lock mid-flight and lands itself safely anyway. The full team
-- (Imani, Lin, Tomas, Sera, Byte) walks flight fundamentals through
-- failsafes; the boss resolves the incident on three fronts at once --
-- an ordinary signal-occlusion cause (not an attack), an IMU-only
-- attitude hold that never wavered, and a controlled-descent failsafe
-- confirmed correct over a blind return-to-home attempt -- closing on
-- the bible's own stated beat and handing off into Act 30's edge AI.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-drones', 'world-vec-drones', 'drones', '6A - Drones', 'Learn how a small multirotor actually stays in the air -- flight fundamentals, frames and axes, the IMU, ESC and motor concepts, the flight controller, attitude, altitude and position control, PX4/ArduPilot concepts, telemetry and failsafes -- while Vector Division brings its first aerial platform online and works out exactly what happened when it lost GPS lock in mid-air.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-drones-1', 'campaign-vec-drones', 'off-the-ground', 'Off the Ground', 'Flight fundamentals, frames and axes, the IMU in flight, ESC and motor concepts, the flight controller and attitude control.', 1),
  ('operation-vec-drones-2', 'campaign-vec-drones', 'the-signal-that-went-quiet', 'The Signal That Went Quiet', 'Altitude control, position control, PX4/ArduPilot concepts, telemetry, failsafes, and the flight that lost its GPS.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-drones-01', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-1', 'flight-fundamentals', 'Flight Fundamentals', 'Vector Division brings its first aerial platform online: a small inspection drone. Days into test flights, it loses GPS lock in mid-air -- and comes down safely anyway. Before Commander Imani Rao lets anyone touch the flight logs, everyone needs the same starting vocabulary: what actually keeps four rotors in the air to begin with.', 'beginner', ARRAY['imani','lin','tomas','sera','byte'], null, null, '{"type":"simulation","simulationId":"flight-fundamentals-sim"}'::jsonb, '{"xp":360,"credits":25}'::jsonb, false, 1),
  ('mission-vec-drones-02', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-1', 'frames-and-axes', 'Frames and Axes', 'A ground robot only ever has to reason about position on a flat floor. A drone has to reason about orientation in three dimensions at once -- and none of that reasoning means anything until everyone agrees which axis is which, and relative to what.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-drones-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"frames-and-axes-sim"}'::jsonb, '{"xp":360,"credits":30}'::jsonb, false, 2),
  ('mission-vec-drones-03', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-1', 'imu-in-flight', 'The IMU in Flight', 'Every attitude estimate this drone ever produces starts with one sensor package bolted to its frame. Understanding what an IMU actually measures, and what it does not, is the first real clue to how the drone survived losing GPS at all.', 'beginner', ARRAY['lin','tomas'], '{"requiredMissionIds":["mission-vec-drones-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"imu-in-flight-sim"}'::jsonb, '{"xp":370,"credits":30}'::jsonb, false, 3),
  ('mission-vec-drones-04', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-1', 'esc-and-motor-concepts', 'ESC and Motor Concepts', 'Four rotors, four motors, four electronic speed controllers -- and not one of them knows what "attitude" means. Tomas Vey walks through how raw commutation timing on a spinning motor turns into something as deliberate as a roll.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-drones-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"esc-and-motor-concepts-sim"}'::jsonb, '{"xp":370,"credits":35}'::jsonb, false, 4),
  ('mission-vec-drones-05', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-1', 'the-flight-controller', 'The Flight Controller', 'Every sensor reading and every motor command in this drone passes through one board. The flight controller is not a metaphor for the sense-think-act loop -- at a few hundred times a second, it is the loop.', 'beginner', ARRAY['tomas','lin'], '{"requiredMissionIds":["mission-vec-drones-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"flight-controller-sim"}'::jsonb, '{"xp":380,"credits":35}'::jsonb, false, 5),
  ('mission-vec-drones-06', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-1', 'attitude-control', 'Attitude Control', 'Wind, a gust off a building, uneven drag on one arm -- something is always trying to tip a hovering drone over. Attitude control is the loop that never stops correcting for it.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-drones-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"attitude-control-sim"}'::jsonb, '{"xp":380,"credits":35}'::jsonb, false, 6),
  ('mission-vec-drones-07', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-2', 'altitude-control', 'Altitude Control', 'Staying level is not the same problem as staying at the right height. Altitude control is a separate loop, with its own sensors, and it never once needed a GPS signal to do its job.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-drones-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"altitude-control-sim"}'::jsonb, '{"xp":390,"credits":40}'::jsonb, false, 7),
  ('mission-vec-drones-08', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-2', 'position-control', 'Position Control', 'Attitude and altitude keep a drone upright and at the right height. Neither one, on its own, keeps it from drifting sideways -- that is a third loop entirely, and it depends on something the other two never needed.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-drones-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"position-control-sim"}'::jsonb, '{"xp":390,"credits":40}'::jsonb, false, 8),
  ('mission-vec-drones-09', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-2', 'px4-and-ardupilot-concepts', 'PX4 and ArduPilot Concepts', 'Nobody at Vector Division wrote this drone''s flight stack from scratch. PX4 and ArduPilot are the two dominant open flight stacks in the field, and understanding their shared architecture explains what was actually running on the board when GPS dropped.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-drones-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"px4-ardupilot-concepts-sim"}'::jsonb, '{"xp":400,"credits":40}'::jsonb, false, 9),
  ('mission-vec-drones-10', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-2', 'telemetry', 'Telemetry', 'The drone was never silent. It streamed telemetry the entire flight, on a channel completely separate from the one carrying pilot commands -- and one specific field in that stream is about to matter more than any other.', 'beginner', ARRAY['byte','imani'], '{"requiredMissionIds":["mission-vec-drones-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"telemetry-sim"}'::jsonb, '{"xp":400,"credits":45}'::jsonb, false, 10),
  ('mission-vec-drones-11', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-2', 'failsafes', 'Failsafes', 'Sera Holt does not wait for an aerial incident to design for one. A drone that loses its position estimate has exactly a few honest options -- and only one of them is safe to attempt with no idea where the drone actually is.', 'beginner', ARRAY['sera','imani'], '{"requiredMissionIds":["mission-vec-drones-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"failsafes-sim"}'::jsonb, '{"xp":410,"credits":45}'::jsonb, false, 11),
  ('mission-vec-drones-12', 'world-vec-drones', 'campaign-vec-drones', 'operation-vec-drones-2', 'loss-of-gps', 'Loss of GPS', 'Every log is in. The drone is on the ground, intact, batteries still warm. Before Vector Division opens Arc VI on anything else, this team owes itself one complete answer: what actually took the GPS signal, how the drone kept itself upright with nothing but inertia, and whether its failsafe made the only correct call available to it.', 'boss', ARRAY['imani','lin','tomas','sera','byte'], '{"requiredMissionIds":["mission-vec-drones-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"loss-of-gps-boss-sim"}'::jsonb, '{"xp":2300,"credits":460,"badgeIds":["loss-of-gps"],"skillXp":{"robotics_fundamentals":330}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-drones-01', 1, 'imani', 'Vector Division has a fully aerial platform online for the first time: a small inspection drone. Three days into test flights, it lost GPS lock about forty meters up -- and it landed itself safely anyway. I want to know exactly why, before we ever fly it near people.'),
  ('mission-vec-drones-01', 2, 'lin', 'Before we read one log line, everyone needs the same four words. Lift, weight, thrust, drag. A hovering drone is not floating -- it is in constant equilibrium, lift and thrust from four spinning rotors exactly canceling weight and drag.'),
  ('mission-vec-drones-01', 3, 'tomas', 'And every gram of that lift starts with a motor spinning at a commanded speed. I have spent years on ground robots. This is the same electronics, the same firmware discipline -- just with nothing underneath it if we get it wrong.'),
  ('mission-vec-drones-01', 4, 'byte', 'One of our ground robots can lose confidence in its position and simply stop where it stands. I already checked -- that option does not exist up there.'),
  ('mission-vec-drones-01', 5, 'sera', 'It does not. In the air, stopping is not a safe state, it is a crash in progress. Whatever kept that drone up when GPS disappeared, it was never allowed to just wait and think about it.'),
  ('mission-vec-drones-01', 6, 'imani', 'Which is exactly what we are here to understand. Flight fundamentals first. Then we earn the right to read what actually happened forty meters over that test field.'),

  ('mission-vec-drones-02', 1, 'lin', 'A ground robot reasons in one flat frame. A drone reasons in three dimensions at once, so the first thing to fix is language: the body frame moves and rotates with the drone itself; the world frame stays fixed to the ground no matter how the drone tips.'),
  ('mission-vec-drones-02', 2, 'lin', 'Inside the body frame there are exactly three rotations. Roll tips the drone side to side around its front-to-back axis. Pitch tips it nose up or down around its side-to-side axis. Yaw spins it left or right around its vertical axis.'),
  ('mission-vec-drones-02', 3, 'byte', 'Every attitude value in this drone''s telemetry log is reported in exactly those terms -- roll, pitch, yaw, body frame versus world frame. Before I can hand you the flight log, you need to be able to read it.'),

  ('mission-vec-drones-03', 1, 'lin', 'Every attitude estimate on this drone starts with one sensor package: the IMU. An accelerometer measures specific force -- mostly gravity plus whatever acceleration the drone itself is undergoing. A gyroscope measures angular rate -- how fast the drone is rotating, right now, about each axis.'),
  ('mission-vec-drones-03', 2, 'tomas', 'I already read sensors like this on our ground robots, just at a slower pace and with lower stakes. Up here the same chip runs every attitude estimate hundreds of times a second, with nothing else to fall back on if it is wrong.'),
  ('mission-vec-drones-03', 3, 'lin', 'And that is the detail worth holding onto. If GPS ever goes quiet, the IMU does not go quiet with it. It is the one sensor package that never depended on a satellite signal in the first place.'),

  ('mission-vec-drones-04', 1, 'tomas', 'None of these four motors know the word "attitude." Each one just receives a commanded speed from an ESC -- an electronic speed controller -- which converts that command into precisely timed current pulses through the motor''s windings.'),
  ('mission-vec-drones-04', 2, 'tomas', 'Attitude comes from doing that unevenly on purpose. Speed up the front pair and slow the back pair, the drone pitches forward. Speed up the left pair and slow the right, it rolls. Adjust diagonal pairs spinning in opposite directions against each other, it yaws.'),
  ('mission-vec-drones-04', 3, 'tomas', 'It looks deliberate from the outside. From the inside it is four independent motors each obeying one number, updated constantly enough that the difference reads as intention.'),

  ('mission-vec-drones-05', 1, 'tomas', 'One board owns all of it -- the flight controller. It reads the IMU, reads every other sensor it has, and outputs commanded speeds to all four ESCs, over and over, hundreds of times a second.'),
  ('mission-vec-drones-05', 2, 'lin', 'That is the sense-think-act loop again, just running faster than anything Vector Division has clocked before. Sense the IMU and other sensors, estimate the drone''s current state, decide a correction, act through the motor mixer.'),
  ('mission-vec-drones-05', 3, 'tomas', 'And unlike a ground robot, there is no pause between cycles worth mentioning. Skip enough cycles up here and the drone does not wait patiently -- it tips.'),

  ('mission-vec-drones-06', 1, 'lin', 'Attitude control is two loops nested inside each other. The inner loop is fast and reads the gyroscope directly -- it corrects angular rate, how quickly the drone is rotating, many times a second.'),
  ('mission-vec-drones-06', 2, 'lin', 'The outer loop is slower and reads the fused attitude estimate -- it corrects angle, how far the drone has actually tipped from level, and feeds its output down into the inner loop as a target rate.'),
  ('mission-vec-drones-06', 3, 'lin', 'Notice what attitude control never once asked for: a GPS fix. It runs entirely on the IMU. Whatever else fails on this drone, attitude control does not need to know where it is, only which way is level.'),

  ('mission-vec-drones-07', 1, 'lin', 'Altitude control answers a different question than attitude control. Attitude asks which way is level. Altitude asks how high off the ground the drone actually is, and it uses its own sensors to answer that: a barometer reading air pressure, backed up by the accelerometer''s vertical estimate.'),
  ('mission-vec-drones-07', 2, 'byte', 'I checked this drone''s configuration directly. Its altitude loop is wired to the barometer and the IMU. It is not wired to GPS altitude at all -- that field exists in the log, but the flight controller was never told to trust it.'),
  ('mission-vec-drones-07', 3, 'lin', 'Which means altitude control, like attitude control, survives a GPS dropout completely intact. Two of the drone''s three control loops never needed that satellite signal in the first place.'),

  ('mission-vec-drones-08', 1, 'lin', 'The third loop is the one that finally does need it. Position control holds the drone over one fixed horizontal spot, and unlike attitude or altitude, it has no onboard sensor that measures absolute position on its own -- it needs an external reference. Normally, that reference is GPS.'),
  ('mission-vec-drones-08', 2, 'byte', 'Take GPS away and position control has nothing left to correct against. Attitude control still keeps the drone level. Altitude control still keeps it at height. But nothing is left holding it over one horizontal point -- it can drift, and nothing on board can tell it that it is drifting.'),
  ('mission-vec-drones-08', 3, 'lin', 'That is the honest shape of the vulnerability. Not a crash. Not a fall. Just one specific loop, out of three, quietly losing the only input it ever had.'),

  ('mission-vec-drones-09', 1, 'tomas', 'This drone did not get its flight stack from scratch. It runs an open flight stack, one of the two the whole field mostly standardizes on: PX4 or ArduPilot. Same shape either way -- sensor drivers feeding a state estimator, the estimator feeding attitude, altitude and position controllers, and a mixer turning all of that into motor commands.'),
  ('mission-vec-drones-09', 2, 'byte', 'The layer that matters most for us right now is the flight mode. Every mode picks which of those controllers actually run, and what each one is allowed to trust.'),
  ('mission-vec-drones-09', 3, 'tomas', 'Which means the honest question is not "did the drone fail." It is "which mode was it actually flying, and what did that mode still have available once GPS was gone."'),

  ('mission-vec-drones-10', 1, 'byte', 'This drone was never silent. It streamed telemetry the entire flight -- attitude, altitude, battery, satellite count -- over a downlink channel to the ground station. That channel is completely separate from the uplink carrying pilot and mode commands.'),
  ('mission-vec-drones-10', 2, 'imani', 'So the pilot''s stick inputs and the telemetry stream never shared a wire, the same way one door incident taught Vector Division months ago on the ground. One direction out, one direction in.'),
  ('mission-vec-drones-10', 3, 'byte', 'And one field in that outbound stream is about to matter more than anything else this Act: GPS fix type and satellite count. It is the first place I would look to find out exactly when this drone actually lost lock.'),

  ('mission-vec-drones-11', 1, 'sera', 'I do not wait for an aerial incident to design for one. A drone that loses position confidence has exactly a few honest failsafe options, and Vector Division has to pick which one runs before this drone ever flies near people.'),
  ('mission-vec-drones-11', 2, 'sera', 'Return-to-home needs a trustworthy position estimate, both to know where home is and to know where the drone currently is relative to it. Position hold, or loiter, needs the same thing. Land needs neither -- it only needs attitude and altitude control, descending in place under control.'),
  ('mission-vec-drones-11', 3, 'imani', 'So if GPS disappears mid-flight, return-to-home is not the safe choice. It is the choice that assumes an estimate the drone no longer has.'),
  ('mission-vec-drones-11', 4, 'sera', 'Exactly. The only failsafe that is honest about what the drone still knows, once GPS is gone, is a controlled landing using nothing but attitude and altitude control. Everything else pretends it still has a position it does not.'),

  ('mission-vec-drones-12', 1, 'imani', 'Every log from that flight is in. The drone is on the ground, intact, batteries still warm from the landing. Before Vector Division calls this closed, I want one complete answer, not three separate guesses.'),
  ('mission-vec-drones-12', 2, 'byte', 'Satellite count and fix type first, like I said they would matter. I can place the exact moment the fix dropped, and correlate it against the drone''s recorded flight path.'),
  ('mission-vec-drones-12', 3, 'lin', 'I want the attitude channel next, not the position channel. If this drone kept itself upright with nothing but inertial sensors, that has to show up as a continuous, stable estimate straight through the dropout, not a gap.'),
  ('mission-vec-drones-12', 4, 'tomas', 'Motor and ESC telemetry never faulted once, start to finish. Whatever happened, it was never a hardware failure on the actuation side. This is a controller and estimator story, not a firmware crash.'),
  ('mission-vec-drones-12', 5, 'sera', 'And I want the failsafe decision itself checked against what the drone actually still knew at that moment -- not against what would have looked best on a dashboard.'),
  ('mission-vec-drones-12', 6, 'imani', 'Then that is the job. Diagnose exactly what took the GPS signal. Trace how the drone held itself level on inertial sensors alone. And confirm whether its failsafe made the only defensible call it had left.'),
  ('mission-vec-drones-12', 7, 'sera', 'Get all three right, and Arc VI opens on a system that worked exactly as designed under real loss. Get one wrong, and we ground this platform until we understand why.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-drones-01-o1', 'mission-vec-drones-01', 1, 'Balance the forces', 'Identify how lift, weight, thrust and drag combine to hold a hovering drone in place.'),
  ('mission-vec-drones-01-o2', 'mission-vec-drones-01', 2, 'Explain why it cannot just stop', 'State why a drone cannot treat stopping and waiting as a safe response the way a ground robot can.'),

  ('mission-vec-drones-02-o1', 'mission-vec-drones-02', 1, 'Tell the axes apart', 'Match roll, pitch and yaw to the rotation each one actually describes.'),
  ('mission-vec-drones-02-o2', 'mission-vec-drones-02', 2, 'Separate body frame from world frame', 'Choose the accurate distinction between the drone''s body frame and the fixed world frame.'),

  ('mission-vec-drones-03-o1', 'mission-vec-drones-03', 1, 'Split the IMU into its two sensors', 'Distinguish what the accelerometer measures from what the gyroscope measures.'),
  ('mission-vec-drones-03-o2', 'mission-vec-drones-03', 2, 'Explain why the IMU survives', 'State why the IMU keeps producing a usable estimate even with no GPS signal at all.'),

  ('mission-vec-drones-04-o1', 'mission-vec-drones-04', 1, 'Find the actuator', 'Identify which piece of evidence describes what actually turns a motor command into motion.'),
  ('mission-vec-drones-04-o2', 'mission-vec-drones-04', 2, 'Map thrust to rotation', 'Match each differential-thrust pattern to the rotation or motion it produces.'),

  ('mission-vec-drones-05-o1', 'mission-vec-drones-05', 1, 'Define the flight controller''s role', 'Choose the accurate description of what a flight controller actually does.'),
  ('mission-vec-drones-05-o2', 'mission-vec-drones-05', 2, 'Order the loop', 'Put the flight controller''s sense-think-act stages in the order they actually run.'),

  ('mission-vec-drones-06-o1', 'mission-vec-drones-06', 1, 'Tell the two loops apart', 'Distinguish the fast inner rate loop from the slower outer angle loop.'),
  ('mission-vec-drones-06-o2', 'mission-vec-drones-06', 2, 'Name attitude control''s one dependency', 'Judge which sensor package attitude control actually depends on.'),

  ('mission-vec-drones-07-o1', 'mission-vec-drones-07', 1, 'Find the altitude sensors', 'Identify which sensors this drone''s altitude loop is actually wired to.'),
  ('mission-vec-drones-07-o2', 'mission-vec-drones-07', 2, 'Separate altitude from attitude', 'Choose the accurate distinction between altitude control and attitude control.'),

  ('mission-vec-drones-08-o1', 'mission-vec-drones-08', 1, 'Name position control''s dependency', 'Choose what position control needs that attitude and altitude control do not.'),
  ('mission-vec-drones-08-o2', 'mission-vec-drones-08', 2, 'Judge what is lost', 'Find the evidence that demonstrates the actual limitation created once position control loses its reference.'),

  ('mission-vec-drones-09-o1', 'mission-vec-drones-09', 1, 'Define the flight stack', 'Choose the accurate description of what an open flight stack like PX4 or ArduPilot actually provides.'),
  ('mission-vec-drones-09-o2', 'mission-vec-drones-09', 2, 'Find the mode with no GPS dependency', 'Identify which flight mode has no dependency on GPS at all.'),

  ('mission-vec-drones-10-o1', 'mission-vec-drones-10', 1, 'Tell telemetry from commands', 'Choose the accurate distinction between the telemetry downlink and the command uplink.'),
  ('mission-vec-drones-10-o2', 'mission-vec-drones-10', 2, 'Find the field that matters', 'Identify which telemetry field is the first place to check for a GPS loss.'),

  ('mission-vec-drones-11-o1', 'mission-vec-drones-11', 1, 'Sort the failsafes', 'Match return-to-home, position hold and land to what each one actually requires to run safely.'),
  ('mission-vec-drones-11-o2', 'mission-vec-drones-11', 2, 'Judge the correct failsafe', 'Given GPS is unavailable, decide which failsafe option is actually safe to attempt.'),

  ('mission-vec-drones-12-o1', 'mission-vec-drones-12', 1, 'Diagnose the GPS loss', 'Find the evidence that explains the real, ordinary cause of the GPS dropout.'),
  ('mission-vec-drones-12-o2', 'mission-vec-drones-12', 2, 'Trace the attitude hold', 'Confirm how the flight controller kept the drone level once GPS was gone.'),
  ('mission-vec-drones-12-o3', 'mission-vec-drones-12', 3, 'Judge the failsafe response', 'Confirm whether the controlled descent was the correct call over an attempted return-to-home.'),
  ('mission-vec-drones-12-o4', 'mission-vec-drones-12', 4, 'Close the incident', 'Having judged all three, state what this flight actually proves about the failsafe stack.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-drones-01-o1-c1', 'mission-vec-drones-01-o1', 1, 'multiple_choice', 'A drone is holding a stable hover. What is actually true about the forces acting on it?', '{"question":"A drone is holding a stable hover. What is actually true about the forces acting on it?","options":[{"id":"a","text":"Only thrust is acting on it, gravity is irrelevant once airborne"},{"id":"b","text":"Lift and thrust from the four rotors exactly balance weight and drag, holding it in equilibrium rather than motionless by default"},{"id":"c","text":"Drag only matters at high forward speed, never in a hover"},{"id":"d","text":"Weight stops applying once the rotors are spinning"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-drones-01-o2-c1', 'mission-vec-drones-01-o2', 1, 'multiple_choice', 'A ground robot that loses confidence in its position can simply stop and wait. Why can a drone not do the same thing?', '{"question":"A ground robot that loses confidence in its position can simply stop and wait. Why can a drone not do the same thing?","options":[{"id":"a","text":"It can, hovering in place is exactly the same as a ground robot stopping"},{"id":"b","text":"Hovering itself requires continuously generating enough thrust to counter gravity -- there is no passive off state in the air that does not immediately become a fall"},{"id":"c","text":"Drones are simply built with weaker motors than ground robots"},{"id":"d","text":"Stopping is fine as long as the battery still has charge"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-drones-02-o1-c1', 'mission-vec-drones-02-o1', 1, 'drag_and_drop', 'Match each description to the rotation it defines.', '{"items":[{"id":"i1","text":"Tipping side to side around the front-to-back axis"},{"id":"i2","text":"Tipping nose up or down around the side-to-side axis"},{"id":"i3","text":"Spinning left or right around the vertical axis"}],"targets":[{"id":"roll","label":"Roll"},{"id":"pitch","label":"Pitch"},{"id":"yaw","label":"Yaw"}]}'::jsonb, '{"correctMapping":{"i1":"roll","i2":"pitch","i3":"yaw"}}'::jsonb),
  ('mission-vec-drones-02-o2-c1', 'mission-vec-drones-02-o2', 1, 'multiple_choice', 'What is the actual difference between the drone''s body frame and the world frame?', '{"question":"What is the actual difference between the drone''s body frame and the world frame?","options":[{"id":"a","text":"They are two names for the same frame"},{"id":"b","text":"The body frame moves and rotates with the drone itself; the world frame stays fixed to the ground regardless of how the drone tips or turns"},{"id":"c","text":"The world frame only exists in simulation, never on real hardware"},{"id":"d","text":"The body frame is only used for altitude, the world frame only for position"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-drones-03-o1-c1', 'mission-vec-drones-03-o1', 1, 'multiple_choice', 'What does each half of the IMU actually measure?', '{"question":"What does each half of the IMU actually measure?","options":[{"id":"a","text":"Both measure the exact same quantity for redundancy"},{"id":"b","text":"The accelerometer measures specific force, largely gravity plus the drone''s own acceleration; the gyroscope measures angular rate, how fast the drone is currently rotating about each axis"},{"id":"c","text":"The accelerometer measures rotation, the gyroscope measures altitude"},{"id":"d","text":"Neither measures anything useful without a GPS fix to calibrate against"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-drones-03-o2-c1', 'mission-vec-drones-03-o2', 1, 'multiple_choice', 'Why does the IMU keep producing a usable attitude estimate even after GPS disappears?', '{"question":"Why does the IMU keep producing a usable attitude estimate even after GPS disappears?","options":[{"id":"a","text":"It does not, it fails at the same time GPS does"},{"id":"b","text":"It was never dependent on a satellite signal in the first place -- it measures the drone''s own acceleration and rotation directly, onboard"},{"id":"c","text":"It automatically switches to GPS as a backup source"},{"id":"d","text":"It only works below a certain altitude"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-drones-04-o1-c1', 'mission-vec-drones-04-o1', 1, 'investigation', 'Which piece of evidence identifies the actual actuator -- the part that turns a command into physical motion?', '{"evidence":[{"id":"e1","label":"Firmware note","detail":"The flight controller outputs a duty cycle command to each ESC hundreds of times a second"},{"id":"e2","label":"Bench test","detail":"A motor draws current and produces torque only while its ESC is actively commutating its windings"},{"id":"e3","label":"Wiring diagram","detail":"The flight controller board sits between the IMU inputs and the ESC outputs"}],"question":"Which piece of evidence identifies the actual actuator -- the part that turns a command into physical motion?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-vec-drones-04-o2-c1', 'mission-vec-drones-04-o2', 1, 'drag_and_drop', 'Match each differential-thrust pattern to the motion it produces.', '{"items":[{"id":"t1","text":"Front pair sped up, back pair slowed down"},{"id":"t2","text":"Left pair sped up, right pair slowed down"},{"id":"t3","text":"Diagonal motor pairs sped up and slowed against each other"},{"id":"t4","text":"All four rotors sped up equally together"}],"targets":[{"id":"pitch","label":"Pitch"},{"id":"roll","label":"Roll"},{"id":"yaw","label":"Yaw"},{"id":"throttle","label":"Throttle (climb)"}]}'::jsonb, '{"correctMapping":{"t1":"pitch","t2":"roll","t3":"yaw","t4":"throttle"}}'::jsonb),

  ('mission-vec-drones-05-o1-c1', 'mission-vec-drones-05-o1', 1, 'multiple_choice', 'What does the flight controller actually do?', '{"question":"What does the flight controller actually do?","options":[{"id":"a","text":"It only stores flight logs for later review"},{"id":"b","text":"It reads every onboard sensor, estimates the drone''s current state, decides a correction, and commands the motors through the mixer -- the entire sense-think-act loop running on one board"},{"id":"c","text":"It only handles the radio link to the pilot"},{"id":"d","text":"It exists only to supply power to the motors"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-drones-05-o2-c1', 'mission-vec-drones-05-o2', 1, 'interactive_diagram', 'Order the flight controller''s loop from raw sensor reading to motor output.', '{"diagramId":"flight-controller-loop","hotspots":[{"id":"sense","label":"Sense","explanation":"Read the IMU and every other onboard sensor."},{"id":"estimate","label":"Estimate","explanation":"Fuse raw sensor data into a current state estimate."},{"id":"control","label":"Control","explanation":"Compare the estimate against the target and decide a correction."},{"id":"mix","label":"Mix","explanation":"Convert the correction into individual commanded speeds for each ESC."}],"task":"Order the stages from raw sensor reading to motor output."}'::jsonb, '{"correctOrderIds":["sense","estimate","control","mix"]}'::jsonb),

  ('mission-vec-drones-06-o1-c1', 'mission-vec-drones-06-o1', 1, 'multiple_choice', 'How do the two attitude control loops differ?', '{"question":"How do the two attitude control loops differ?","options":[{"id":"a","text":"They are identical, just running twice for redundancy"},{"id":"b","text":"The inner rate loop reads the gyroscope directly and corrects angular rate many times a second; the outer angle loop reads the fused attitude estimate, corrects how far off level the drone actually is, and feeds a target rate down to the inner loop"},{"id":"c","text":"The outer loop runs faster than the inner loop"},{"id":"d","text":"Only one of the two loops ever runs at a time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-drones-06-o2-c1', 'mission-vec-drones-06-o2', 1, 'multiple_choice', 'Which sensor package does attitude control actually depend on?', '{"question":"Which sensor package does attitude control actually depend on?","options":[{"id":"a","text":"GPS, to know its position before correcting its angle"},{"id":"b","text":"The IMU alone -- attitude control only needs to know which way is level, never where the drone actually is"},{"id":"c","text":"The barometer alone"},{"id":"d","text":"The telemetry radio link"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-drones-07-o1-c1', 'mission-vec-drones-07-o1', 1, 'investigation', 'Which sensors is this drone''s altitude control loop actually wired to?', '{"evidence":[{"id":"e1","label":"Configuration record","detail":"This drone''s altitude control loop reads its barometer and the IMU''s vertical acceleration estimate"},{"id":"e2","label":"Configuration record","detail":"GPS altitude is logged for reference but the altitude controller is never configured to use it as an input"},{"id":"e3","label":"Facilities note","detail":"The drone''s barometer was calibrated against ground-level pressure before the flight"}],"question":"Which sensors is this drone''s altitude control loop actually wired to?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-drones-07-o2-c1', 'mission-vec-drones-07-o2', 1, 'multiple_choice', 'What is the real difference between altitude control and attitude control?', '{"question":"What is the real difference between altitude control and attitude control?","options":[{"id":"a","text":"They are the same loop under two names"},{"id":"b","text":"Attitude control asks which way is level; altitude control asks how high off the ground the drone actually is -- two separate loops with two separate jobs"},{"id":"c","text":"Altitude control only matters while climbing, never while descending"},{"id":"d","text":"Attitude control only runs indoors"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-drones-08-o1-c1', 'mission-vec-drones-08-o1', 1, 'multiple_choice', 'What does position control need that attitude and altitude control do not?', '{"question":"What does position control need that attitude and altitude control do not?","options":[{"id":"a","text":"Nothing, all three loops use exactly the same inputs"},{"id":"b","text":"An external absolute reference for horizontal position -- normally GPS -- because nothing onboard measures the drone''s horizontal location on its own"},{"id":"c","text":"A faster processor than the other two loops"},{"id":"d","text":"A second flight controller board"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-drones-08-o2-c1', 'mission-vec-drones-08-o2', 1, 'investigation', 'Which evidence demonstrates the actual limitation created once position control loses its reference?', '{"evidence":[{"id":"e1","label":"Flight log","detail":"Roll, pitch and yaw estimates stayed continuous and stable through the entire GPS dropout"},{"id":"e2","label":"Flight log","detail":"Altitude held within normal tolerance through the entire GPS dropout"},{"id":"e3","label":"Flight log","detail":"Horizontal position drifted with no correction applied for the duration of the GPS dropout"}],"question":"Which evidence demonstrates the actual limitation created once position control loses its reference?"}'::jsonb, '{"requiredEvidenceIds":["e3"]}'::jsonb),

  ('mission-vec-drones-09-o1-c1', 'mission-vec-drones-09-o1', 1, 'multiple_choice', 'What does an open flight stack like PX4 or ArduPilot actually provide?', '{"question":"What does an open flight stack like PX4 or ArduPilot actually provide?","options":[{"id":"a","text":"A proprietary black box no engineer can inspect"},{"id":"b","text":"A shared, tested architecture -- sensor drivers, a state estimator, attitude, altitude and position controllers, and a mixer -- so no team has to rebuild that whole stack from scratch for every new airframe"},{"id":"c","text":"Only a radio protocol, nothing about control loops"},{"id":"d","text":"A single fixed flight mode with no configuration"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-drones-09-o2-c1', 'mission-vec-drones-09-o2', 1, 'browser_simulation', 'Which flight mode has no dependency on GPS at all?', '{"screen":"GROUND CONTROL STATION -- FLIGHT MODE REFERENCE","question":"Which flight mode has no dependency on GPS at all?","records":[{"id":"m1","code":"MANUAL","detail":"Pilot stick inputs pass straight to the motor mixer, no sensor-based stabilization requested"},{"id":"m2","code":"STABILIZE","detail":"Flight controller holds attitude using the IMU only, pilot commands lean angle directly"},{"id":"m3","code":"POSITION_HOLD","detail":"Flight controller holds a fixed horizontal position and altitude using GPS combined with the IMU and barometer"},{"id":"m4","code":"RETURN_TO_LAUNCH","detail":"Flight controller navigates back to a recorded home coordinate using GPS combined with the IMU"}]}'::jsonb, '{"correctOptionId":"m2"}'::jsonb),

  ('mission-vec-drones-10-o1-c1', 'mission-vec-drones-10-o1', 1, 'multiple_choice', 'How do this drone''s telemetry downlink and command uplink actually differ?', '{"question":"How do this drone''s telemetry downlink and command uplink actually differ?","options":[{"id":"a","text":"They are the same radio channel, just labeled differently"},{"id":"b","text":"Telemetry reports the drone''s own state outward to the ground station; commands carry pilot and mode instructions inward to the drone -- opposite directions, on separate channels"},{"id":"c","text":"Telemetry only exists after landing"},{"id":"d","text":"Commands are only sent during takeoff and landing"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-drones-10-o2-c1', 'mission-vec-drones-10-o2', 1, 'investigation', 'Which telemetry field is the first place to check to find out exactly when this drone lost its GPS lock?', '{"evidence":[{"id":"e1","label":"Telemetry schema","detail":"Battery voltage and current are logged every flight"},{"id":"e2","label":"Telemetry schema","detail":"GPS fix type and satellite count are logged as a distinct field, separate from the position estimate itself"},{"id":"e3","label":"Telemetry schema","detail":"Motor RPM is logged for each of the four motors"}],"question":"Which telemetry field is the first place to check to find out exactly when this drone lost its GPS lock?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-drones-11-o1-c1', 'mission-vec-drones-11-o1', 1, 'drag_and_drop', 'Match each failsafe option to what it actually requires to run safely.', '{"items":[{"id":"f1","text":"Return-to-home"},{"id":"f2","text":"Position hold / loiter"},{"id":"f3","text":"Land in place"}],"targets":[{"id":"needs_position","label":"Needs a trustworthy position estimate"},{"id":"needs_att_alt_only","label":"Needs only attitude and altitude control"}]}'::jsonb, '{"correctMapping":{"f1":"needs_position","f2":"needs_position","f3":"needs_att_alt_only"}}'::jsonb),
  ('mission-vec-drones-11-o2-c1', 'mission-vec-drones-11-o2', 1, 'multiple_choice', 'GPS is unavailable and no reliable position estimate exists. Which failsafe response is actually safe to attempt?', '{"question":"GPS is unavailable and no reliable position estimate exists. Which failsafe response is actually safe to attempt?","options":[{"id":"a","text":"Return-to-home, because getting the drone back to its start point is always the priority"},{"id":"b","text":"A controlled landing in place, using only attitude and altitude control, since it is the only option that does not assume a position estimate the drone no longer has"},{"id":"c","text":"Position hold, to keep the drone exactly where it is until GPS returns"},{"id":"d","text":"Cut all motor power immediately to prevent further drift"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-drones-12-o1-c1', 'mission-vec-drones-12-o1', 1, 'investigation', 'Which piece of evidence explains the actual, ordinary cause of the GPS loss?', '{"evidence":[{"id":"e1","label":"Flight log","detail":"GPS fix quality dropped from a stable 3D fix to no fix in under two seconds as the drone passed within meters of a tall steel-frame structure, consistent with signal occlusion and multipath, with no similar drop anywhere else in the flight"},{"id":"e2","label":"RF spectrum log","detail":"No anomalous RF energy anywhere in the GPS L1 band throughout the flight, nothing consistent with jamming"},{"id":"e3","label":"GPS module diagnostic","detail":"The GPS receiver reported no fix, but its power rail, heartbeat and internal self-test all stayed nominal throughout -- the module itself never failed"}],"question":"Which piece of evidence explains the actual, ordinary cause of the GPS loss?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-drones-12-o2-c1', 'mission-vec-drones-12-o2', 1, 'multiple_choice', 'Once GPS dropped, what do the flight logs actually show about the drone''s attitude?', '{"question":"Once GPS dropped, what do the flight logs actually show about the drone''s attitude?","options":[{"id":"a","text":"Roll, pitch and yaw estimates became erratic and eventually invalid, the same moment GPS dropped"},{"id":"b","text":"The attitude estimate stayed continuous and stable straight through the dropout, sourced entirely from the IMU, because attitude control never depended on GPS in the first place"},{"id":"c","text":"The flight controller froze all outputs the moment GPS was lost"},{"id":"d","text":"Attitude control switched over to a backup GPS-derived estimate"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-drones-12-o3-c1', 'mission-vec-drones-12-o3', 1, 'multiple_choice', 'With no reliable position estimate available, was a controlled landing in place the correct failsafe response, or should the drone have attempted return-to-home?', '{"question":"With no reliable position estimate available, was a controlled landing in place the correct failsafe response, or should the drone have attempted return-to-home?","options":[{"id":"a","text":"Return-to-home, because reaching the home point matters more than exactly where it lands"},{"id":"b","text":"The controlled landing was correct -- return-to-home requires a trustworthy position estimate that no longer existed, so attempting it would have meant navigating blind"},{"id":"c","text":"Neither, the drone should have simply cut power and fallen"},{"id":"d","text":"Return-to-home, because a failsafe should always try to recover the aircraft first"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-drones-12-o4-c1', 'mission-vec-drones-12-o4', 1, 'boss_encounter', 'Having diagnosed the cause, traced the attitude hold and judged the failsafe response, state what this flight actually proves.', '{"stages":[{"objectiveRef":"mission-vec-drones-12-o1","label":"Diagnose the GPS loss"},{"objectiveRef":"mission-vec-drones-12-o2","label":"Trace the attitude hold"},{"objectiveRef":"mission-vec-drones-12-o3","label":"Judge the failsafe response"}],"task":"State the full incident conclusion in one pass: what actually took the GPS signal, how the drone stayed upright with nothing but its own inertial sensors, and why its failsafe made the correct call."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-drones-12-o1","mission-vec-drones-12-o2","mission-vec-drones-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-drones-01-o1-c1', 'orientation', 'A hover is not a resting state -- ask what is being continuously balanced against what.', 10, 1),
  ('mission-vec-drones-01-o1-c1', 'solution', 'Lift and thrust from the four rotors exactly balance weight and drag -- a hover is active equilibrium, not rest.', 20, 2),
  ('mission-vec-drones-01-o2-c1', 'orientation', 'Think about what keeps a drone up in the first place, and whether that thing can simply switch off.', 10, 1),
  ('mission-vec-drones-01-o2-c1', 'solution', 'Hovering requires continuously fighting gravity -- there is no passive off state in the air that is not also a fall.', 20, 2),

  ('mission-vec-drones-02-o1-c1', 'orientation', 'Match each axis name to which direction of the drone it tips or spins around.', 10, 1),
  ('mission-vec-drones-02-o1-c1', 'solution', 'Roll is side-to-side tipping around the front-to-back axis, pitch is nose up-down around the side-to-side axis, yaw is spinning around the vertical axis.', 20, 2),
  ('mission-vec-drones-02-o2-c1', 'orientation', 'Ask which frame moves with the drone, and which one never does.', 10, 1),
  ('mission-vec-drones-02-o2-c1', 'solution', 'The body frame moves and rotates with the drone; the world frame stays fixed to the ground regardless of the drone''s orientation.', 20, 2),

  ('mission-vec-drones-03-o1-c1', 'orientation', 'One half of the IMU measures force, the other measures rotation rate -- they are not the same quantity.', 10, 1),
  ('mission-vec-drones-03-o1-c1', 'solution', 'The accelerometer measures specific force (gravity plus the drone''s own acceleration); the gyroscope measures angular rate.', 20, 2),
  ('mission-vec-drones-03-o2-c1', 'orientation', 'Ask what the IMU actually needs from outside itself to produce a reading.', 10, 1),
  ('mission-vec-drones-03-o2-c1', 'solution', 'The IMU measures the drone''s own motion directly, onboard -- it never depended on a satellite signal to begin with.', 20, 2),

  ('mission-vec-drones-04-o1-c1', 'orientation', 'An actuator is whatever converts a command into physical force or motion.', 10, 1),
  ('mission-vec-drones-04-o1-c1', 'solution', 'e2: the motor only produces torque while its ESC is actively commutating it -- that is the actuator.', 20, 2),
  ('mission-vec-drones-04-o2-c1', 'orientation', 'Think about which pair of rotors is being sped up relative to which other pair.', 10, 1),
  ('mission-vec-drones-04-o2-c1', 'solution', 'Front/back differential produces pitch, left/right differential produces roll, opposing diagonal-pair differential produces yaw, and equal increase on all four produces throttle.', 20, 2),

  ('mission-vec-drones-05-o1-c1', 'orientation', 'Think about everything the board reads, decides and outputs, not just one of those steps.', 10, 1),
  ('mission-vec-drones-05-o1-c1', 'solution', 'It reads sensors, estimates state, decides a correction and commands the motors -- the whole sense-think-act loop on one board.', 20, 2),
  ('mission-vec-drones-05-o2-c1', 'orientation', 'Nothing can be corrected before it has been measured and estimated first.', 10, 1),
  ('mission-vec-drones-05-o2-c1', 'solution', 'Sense, then estimate, then control, then mix -- and the loop repeats from sense again.', 20, 2),

  ('mission-vec-drones-06-o1-c1', 'orientation', 'One loop reads a rate sensor directly, the other reads a fused estimate and feeds the first loop a target.', 10, 1),
  ('mission-vec-drones-06-o1-c1', 'solution', 'The inner rate loop corrects angular rate from the gyroscope; the outer angle loop corrects tilt from the fused estimate and feeds the inner loop a target rate.', 20, 2),
  ('mission-vec-drones-06-o2-c1', 'orientation', 'Attitude control only needs to answer "which way is level," never "where am I."', 10, 1),
  ('mission-vec-drones-06-o2-c1', 'solution', 'Attitude control depends on the IMU alone -- it never needs a position fix to hold level.', 20, 2),

  ('mission-vec-drones-07-o1-c1', 'orientation', 'Look for the configuration record, not the calibration note.', 10, 1),
  ('mission-vec-drones-07-o1-c1', 'solution', 'e1: the altitude loop is wired to the barometer and the IMU''s vertical estimate, not to GPS altitude.', 20, 2),
  ('mission-vec-drones-07-o2-c1', 'orientation', 'One loop answers "which way is level," the other answers "how high."', 10, 1),
  ('mission-vec-drones-07-o2-c1', 'solution', 'Attitude control is about tilt; altitude control is about height -- two separate loops with two separate jobs.', 20, 2),

  ('mission-vec-drones-08-o1-c1', 'orientation', 'Ask what quantity nothing onboard can measure directly, unlike tilt or height.', 10, 1),
  ('mission-vec-drones-08-o1-c1', 'solution', 'Position control needs an external absolute reference, normally GPS, because horizontal location cannot be measured onboard the way tilt and height can.', 20, 2),
  ('mission-vec-drones-08-o2-c1', 'orientation', 'Two of the three logs show something holding steady -- one shows something that is not.', 10, 1),
  ('mission-vec-drones-08-o2-c1', 'solution', 'e3: horizontal position drifted with no correction applied -- that is the actual limitation once position control loses its reference.', 20, 2),

  ('mission-vec-drones-09-o1-c1', 'orientation', 'Ask what a team would otherwise have to rebuild for every new airframe.', 10, 1),
  ('mission-vec-drones-09-o1-c1', 'solution', 'A flight stack like PX4 or ArduPilot provides the shared, tested architecture -- drivers, estimator, controllers, mixer -- so nobody rebuilds it from scratch.', 20, 2),
  ('mission-vec-drones-09-o2-c1', 'orientation', 'Two of the four modes explicitly mention GPS in their description -- rule those out first.', 10, 1),
  ('mission-vec-drones-09-o2-c1', 'solution', 'STABILIZE holds attitude using the IMU only -- it is the one mode with no GPS dependency at all.', 20, 2),

  ('mission-vec-drones-10-o1-c1', 'orientation', 'Ask which direction each one travels: outward to be observed, or inward to command something.', 10, 1),
  ('mission-vec-drones-10-o1-c1', 'solution', 'Telemetry reports state outward on a downlink; commands travel inward on a separate uplink -- opposite directions, separate channels.', 20, 2),
  ('mission-vec-drones-10-o2-c1', 'orientation', 'Look for the field that reports the satellite fix directly, not one that reports something else entirely.', 10, 1),
  ('mission-vec-drones-10-o2-c1', 'solution', 'e2: GPS fix type and satellite count is the field to check first for exactly when lock was lost.', 20, 2),

  ('mission-vec-drones-11-o1-c1', 'orientation', 'Two of the three failsafes need to know where the drone is; one only needs to know which way is level and how high it is.', 10, 1),
  ('mission-vec-drones-11-o1-c1', 'solution', 'Return-to-home and position hold both need a trustworthy position estimate; land only needs attitude and altitude control.', 20, 2),
  ('mission-vec-drones-11-o2-c1', 'orientation', 'Ask which failsafe option does not require an estimate the drone no longer has.', 10, 1),
  ('mission-vec-drones-11-o2-c1', 'solution', 'A controlled landing in place is the only failsafe that does not assume a position estimate the drone has already lost.', 20, 2),

  ('mission-vec-drones-12-o1-c1', 'orientation', 'One record explains the timing and location of the drop, one rules out jamming, one rules out hardware failure -- only one actually explains the cause.', 15, 1),
  ('mission-vec-drones-12-o1-c1', 'solution', 'e1: fix quality dropped precisely as the drone passed close to a tall structure -- signal occlusion and multipath, an ordinary cause, not an attack.', 25, 2),
  ('mission-vec-drones-12-o2-c1', 'orientation', 'Recall which control loop this Act already proved never needed GPS at all.', 15, 1),
  ('mission-vec-drones-12-o2-c1', 'solution', 'Attitude stayed continuous and stable through the dropout because attitude control was always running on the IMU alone.', 25, 2),
  ('mission-vec-drones-12-o3-c1', 'orientation', 'Recall which failsafe this Act already proved does not require a position estimate.', 15, 1),
  ('mission-vec-drones-12-o3-c1', 'solution', 'The controlled landing was correct -- return-to-home would have required navigating blind on a position estimate that no longer existed.', 25, 2),
  ('mission-vec-drones-12-o4-c1', 'orientation', 'Line up the three judgments: the cause, the attitude hold, and the failsafe choice, into one connected account.', 15, 1),
  ('mission-vec-drones-12-o4-c1', 'solution', 'An ordinary occlusion took the GPS signal; the IMU-only attitude loop held the drone level through the dropout exactly as designed; and the controlled descent was the only failsafe honest about what the drone still knew -- the stack worked correctly under real loss.', 25, 2);
